head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf20000p";
scwin._popupWindow = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — result, std_cd_grnt_start_dd, std_cd_grnt_end_dd, curDate

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_stdCdGrntStartDd();
        scwin.init_datefmt_cal_stdCdGrntEndDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf20000p.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "ul_68", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_result", fn: function(){ return (!(String(((dma_pageContext.get("result") ?? "")) == null ? '' : ((dma_pageContext.get("result") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_searchRadio", fn: function () { return String(String((dma_pageContext.get("searchRadio") ?? ""))); } },
        { childId: "cal_stdCdGrntStartDd", fn: function () { return String((dma_pageContext.get("stdCdGrntStartDd") ?? "")); } },
        { childId: "cal_stdCdGrntEndDd", fn: function () { return String((dma_pageContext.get("stdCdGrntEndDd") ?? "")); } },
        { childId: "ipt_comNm", fn: function () { return String((dma_pageContext.get("comNm") ?? "")); } },
        { childId: "ipt_isurNm", fn: function () { return String((dma_pageContext.get("isurNm") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntStartDd
 * @description 초기화 — datefmt cal std Cd Grnt Start Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_stdCdGrntStartDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntStartDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntEndDd
 * @description 초기화 — datefmt cal std Cd Grnt End Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_stdCdGrntEndDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const std_cd_grnt_start_dd = (String(((dma_pageContext.get("std_cd_grnt_start_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_start_dd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("std_cd_grnt_start_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_start_dd") ?? ""))));
        const std_cd_grnt_end_dd = (String(((dma_pageContext.get("std_cd_grnt_end_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_end_dd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("std_cd_grnt_end_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_end_dd") ?? ""))));
        if (std_cd_grnt_start_dd !== "") {
            if (std_cd_grnt_start_dd.length === 8) {
                $c.util.getComponent('cal_stdCdGrntStartDd').setValue($c.date.dateFormat(std_cd_grnt_start_dd));
            } else {
                $c.util.getComponent('cal_stdCdGrntStartDd').setValue(std_cd_grnt_start_dd);
            }
        }
        if (std_cd_grnt_end_dd !== "") {
            if (std_cd_grnt_end_dd.length === 8) {
                $c.util.getComponent('cal_stdCdGrntEndDd').setValue($c.date.dateFormat(std_cd_grnt_end_dd));
            } else {
                $c.util.getComponent('cal_stdCdGrntEndDd').setValue(std_cd_grnt_end_dd);
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000p.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_onPopupCode, tx_fn_search) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_appDate2_onclick
 * @description btn_appDate2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_onclick = function(e){
    try {
        scwin.appDate2('stdCdGrntStartDd','stdCdGrntEndDd',3)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_appDate2_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_2_onclick
 * @description btn_appDate2_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_2_onclick = function(e){
    try {
        scwin.appDate2('stdCdGrntStartDd','stdCdGrntEndDd',6)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_appDate2_2_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_3_onclick
 * @description btn_appDate2_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_3_onclick = function(e){
    try {
        scwin.appDate2('stdCdGrntStartDd','stdCdGrntEndDd',12)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_appDate2_3_onclick' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_search_onclick' }); }
};

/**
 * @method
 * @name dataTb_oncellclick
 * @description dataTb 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["mktNm"] !== '14') { await scwin.onPopupCode(r["mktNm"], r["stdCd"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.oncellclick' });
    }
};

/**
 * @method
 * @name btn_window_onclick
 * @description btn_window 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_window_onclick' }); }
};

/**
 * @method
 * @name btn_window_onfocus
 * @description btn_window 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.blur()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000p.btn_window_onfocus' }); }
};

/**
 * @method
 * @name tx_onPopupCode
 * @description on Popup Code 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_onPopupCode = async function () {
    try {
        const sbmOptions = {
            id: "tx_onPopupCode",
            method: "post",
            action: "/srch/srch.do?method=srchPopup",
            ref: "dma_onPopupCodeReq",
            target: "dlt_result=body.content",
            isProcessMsg: false
        };
        const res = await $c.sbm.executeDynamic(sbmOptions);
        if (res && res.skipped) { return res; }  // 중복 제출 skip
        if (!(res && res.responseJSON && res.responseJSON.success === true)) {
            const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
            await $c.win.alert(m);
        }
        return res;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldinf20000p.tx_onPopupCode" });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_127_onclick
 * @description krxpage_pagenavigator_127 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_127_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        await scwin.search(index);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldinf20000p.krxpage_pagenavigator_127_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/srch/srch.do?method=srchPopupList",
        ref: "dma_searchReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appDate2
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {String} startId startId
 * @param {String} endId endId
 * @param {*} months months
 * @returns {void}
 * @hidden N
 */
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name dataTb_fmt_stdCd
 * @description data Tb fmt std Cd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataTb_fmt_stdCd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "mktNm") ?? '') : '');
        if (v !== '14') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "stdCd") : '') ?? '') + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "dataTb.stdCd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name dateSetting
 * @description date Setting 처리
 * @returns {void}
 * @hidden N
 */
scwin.dateSetting = function () {
    const curDate = (String(((dma_pageContext.get("curDate") ?? "")) == null ? '' : ((dma_pageContext.get("curDate") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("curDate") ?? "")) == null ? '' : ((dma_pageContext.get("curDate") ?? ""))));
    const curYY = curDate.substring(0, 4);
    const curMM = curDate.substring(4, 6);
    const curDD = curDate.substring(6, 8);
    const intCurYY = Number(curYY);
    const intCurMM = Number(curMM);
    let bfOneYY = "";
    let bfOneMM = "";
    let calMM = intCurMM - 1;
    if (calMM < 0) {
        bfOneYY = intCurYY - 1;
        bfOneMM = 12 + calMM;
    } else {
        bfOneYY = intCurYY;
        bfOneMM = calMM;
    }
    let bfThreeYY = "";
    let bfThreeMM = "";
    calMM = intCurMM - 3;
    if (calMM < 0) {
        bfThreeYY = intCurYY - 1;
        bfThreeMM = 12 + calMM;
    } else {
        bfThreeYY = intCurYY;
        bfThreeMM = calMM;
    }
    let bfSixYY = "";
    let bfSixMM = "";
    calMM = intCurMM - 6;
    if (calMM < 0) {
        bfSixYY = intCurYY - 1;
        bfSixMM = 12 + calMM;
    } else {
        bfSixYY = intCurYY;
        bfSixMM = calMM;
    }
    const oneDD = new Date(bfOneYY, bfOneMM, curDD);
    const threeDD = new Date(bfThreeYY, bfThreeMM, curDD);
    const sixDD = new Date(bfSixYY, bfSixMM, curDD);
    if (Number(bfOneMM) < 10) {
        bfOneMM = "0" + bfOneMM;
    }
    if (Number(bfThreeMM) < 10) {
        bfThreeMM = "0" + bfThreeMM;
    }
    if (Number(bfSixMM) < 10) {
        bfSixMM = "0" + bfSixMM;
    }
    const oneD = (Number(oneDD.getMonth()) < 10) ? ("0" + oneDD.getMonth()) : oneDD.getMonth();
    const ThD = (Number(threeDD.getMonth()) < 10) ? ("0" + threeDD.getMonth()) : threeDD.getMonth();
    const SxD = (Number(sixDD.getMonth()) < 10) ? ("0" + sixDD.getMonth()) : sixDD.getMonth();
    const oneDt = (Number(oneDD.getDate()) < 10) ? ("0" + oneDD.getDate()) : oneDD.getDate();
    const ThDt = (Number(threeDD.getDate()) < 10) ? ("0" + threeDD.getDate()) : threeDD.getDate();
    const SxDt = (Number(sixDD.getDate()) < 10) ? ("0" + sixDD.getDate()) : sixDD.getDate();
    const bfOneDate = oneDD.getFullYear() + oneD + oneDt;
    const bfThreeDate = threeDD.getFullYear() + ThD + ThDt;
    const bfSixDate = sixDD.getFullYear() + SxD + SxDt;
    $c.util.getComponent('dma_hiddenStore').set('ipt_hdOneDate', bfOneDate);
    $c.util.getComponent('dma_hiddenStore').set('ipt_hdThreeDate', bfThreeDate);
    $c.util.getComponent('dma_hiddenStore').set('ipt_hdSixDate', bfSixDate);
};

/**
 * @method
 * @name onPopupCode
 * @description on Popup Code 처리
 * @param {*} type type
 * @param {String} ipt_stdCd ipt_stdCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onPopupCode = async function (type, ipt_stdCd) {
    const fm = (document.popup_form || { elements: [] });
    scwin._popupWindow = $c.win.openPopup("/jldinf20000p/jldinf20000p.xml", { id: "winPop", scrollbars: true, resizable: false, width: "1000", height: "670", type: "pageFramePopup" }, ($c.util.getComponent("dma_onPopupCodeReq") ? $c.util.getComponent("dma_onPopupCodeReq").getJSON() : {}));
    if (type === "122") {
        type = "12";
    }
    $c.util.getComponent('ipt_stdcdType').setValue(type);
    $c.util.getComponent('ipt_stdCd').setValue(ipt_stdCd);
    fm.action = "/srch/srch.do?method=srchPopup" + type;

};

/**
 * @method
 * @name open_corp_cd
 * @description open corp cd 처리
 * @param {*} item_id item_id
 * @param {*} item_nm item_nm
 * @returns {void}
 * @hidden N
 */
scwin.open_corp_cd = function (item_id, item_nm) {
    formName = (document.JLDINF20000p || { elements: [] });
    fn_popupCorpSearch2(formName, item_id, item_nm);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (idx) {
    const srIdx = $('input[name=ipt_searchRadio]:checked').val();
    let ck_stat_cd = "";
    const ckArr = $('input[name=list_cd3]:checked');
    const statLeng = ckArr.length;
    if (statLeng > 0) {
        for (let i = 0; i < statLeng; i++) {
            ck_stat_cd = ck_stat_cd + ((ck_stat_cd === "") ? "'" + $(ckArr[i]).val() + "'" : ",'" + $(ckArr[i]).val() + "'");
        }
    }
    $c.util.getComponent('ipt_listCd').setValue(ck_stat_cd);
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    blockLoading();
    await scwin.tx_fn_search();
};
